package com.stockflow.inventory;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="inventory_movement_line") @Getter @NoArgsConstructor public class InventoryMovementLine { @Id private UUID id; @Column(name="movement_id",nullable=false) private UUID movementId; @Column(name="product_variant_id",nullable=false) private UUID variantId; @Column(name="location_id",nullable=false) private UUID locationId; @Column(nullable=false,precision=19,scale=6) private BigDecimal quantity; @Column(name="unit_cost",nullable=false,precision=19,scale=4) private BigDecimal unitCost; private String lotKey; public InventoryMovementLine(UUID m,UUID v,UUID l,BigDecimal q,BigDecimal c,String lot){id=UUID.randomUUID();movementId=m;variantId=v;locationId=l;quantity=q;unitCost=c;lotKey=lot;}}
